using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PurgingEruptionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Sothis/PurgingEruptionCustomDescription", order = 0)]
public class PurgingEruptionCustomDescription : WhereXTimesCustomDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		PurgingEruptionAction purgingEruptionAction = battleAction as PurgingEruptionAction;
		return string.Concat(purgingEruptionAction.EffectAction.GetActionDescription(purgingEruptionAction.EffectAmount) + "\n", GetActionDescription(amountModified, battleAction, purgingEruptionAction.PurifyAction));
	}
}
